public static int countDoubles(int[] numbers) {
    if (numbers == null || numbers.length == 0) {
        return 0;
    }
    Map<Integer, Integer> freq = new HashMap<>();
    for (int num : numbers) {
        freq.put(num, freq.getOrDefault(num, 0) + 1);
    }
    int count = 0;
    for (int num : numbers) {
        if (num % 2 == 0) {
            int half = num / 2;
            Integer halfCount = freq.get(half);
            if (halfCount != null) {
                if (half != num || halfCount > 1) {
                    count++;
                }
            }
        }
    }
    return count;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    try {
        if (n <= 0 || paths == null) {
            return "cannot be travelled";
        }
        // Determine whether paths represent 2D coordinates (length 4) or linear node IDs (length 2)
        boolean is2D = paths.length > 0 && paths[0].length == 4;
        if (is2D) {
            // Build adjacency for 2D grid
            Map<String, List<String>> graph = new HashMap<>();
            for (int[] p : paths) {
                if (p.length != 4) continue;
                String a = p[0] + "#" + p[1];
                String b = p[2] + "#" + p[3];
                graph.computeIfAbsent(a, k -> new ArrayList<>()).add(b);
                graph.computeIfAbsent(b, k -> new ArrayList<>()).add(a);
            }
            String startKey = (start.length >= 2 ? start[0] + "#" + start[1] : "0#0");
            String endKey = (end.length >= 2 ? end[0] + "#" + end[1] : "0#0");
            Set<String> visited = new HashSet<>();
            Deque<String> queue = new ArrayDeque<>();
            queue.offer(startKey);
            visited.add(startKey);
            while (!queue.isEmpty()) {
                String cur = queue.poll();
                if (cur.equals(endKey)) {
                    return "can be travelled";
                }
                for (String nb : graph.getOrDefault(cur, Collections.emptyList())) {
                    if (!visited.contains(nb)) {
                        visited.add(nb);
                        queue.offer(nb);
                    }
                }
            }
            return "cannot be travelled";
        } else {
            // Treat nodes as integer IDs
            Map<Integer, List<Integer>> graph = new HashMap<>();
            for (int[] p : paths) {
                if (p.length != 2) continue;
                int a = p[0], b = p[1];
                graph.computeIfAbsent(a, k -> new ArrayList<>()).add(b);
                graph.computeIfAbsent(b, k -> new ArrayList<>()).add(a);
            }
            int startNode = start.length > 0 ? start[0] : 0;
            int endNode = end.length > 0 ? end[0] : 0;
            Set<Integer> visited = new HashSet<>();
            Deque<Integer> queue = new ArrayDeque<>();
            queue.offer(startNode);
            visited.add(startNode);
            while (!queue.isEmpty()) {
                int cur = queue.poll();
                if (cur == endNode) {
                    return "can be travelled";
                }
                for (int nb : graph.getOrDefault(cur, Collections.emptyList())) {
                    if (!visited.contains(nb)) {
                        visited.add(nb);
                        queue.offer(nb);
                    }
                }
            }
            return "cannot be travelled";
        }
    } catch (Exception e) {
        return "cannot be travelled";
    }
}

public static String convertDatesToWeekdays(String date) {
    if (date == null || date.trim().isEmpty()) {
        return null;
    }
    java.time.format.DateTimeFormatter formatter =
            java.time.format.DateTimeFormatter.ofPattern("MM dd yyyy");
    java.time.LocalDate localDate;
    try {
        localDate = java.time.LocalDate.parse(date.trim(), formatter);
    } catch (java.time.format.DateTimeParseException e) {
        return null;
    }
    String month = localDate.getMonth()
            .getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);
    int day = localDate.getDayOfMonth();
    int year = localDate.getYear();
    String weekday = localDate.getDayOfWeek()
            .getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);
    return month + " " + day + ", " + year + " is a " + weekday;
}

public int[] twoSum(int[] nums, int target) {
    // Handle null or insufficient length
    if (nums == null) {
        throw new IllegalArgumentException("Input array cannot be null.");
    }
    if (nums.length < 2) {
        return new int[] { -1, -1 };
    }

    java.util.Map<Integer, Integer> map = new java.util.HashMap<>();
    for (int i = 0; i < nums.length; i++) {
        int complement = target - nums[i];
        if (map.containsKey(complement)) {
            return new int[] { map.get(complement), i };
        }
        // Store the current number and its index
        // If the same number appears again, keep the first index only
        map.putIfAbsent(nums[i], i);
    }
    // In case no solution is found (should not happen as per problem statement)
    return new int[] { -1, -1 };
}

public int search(int[] nums, int target) {
    if (nums == null || nums.length == 0) return -1;
    int left = 0, right = nums.length - 1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (nums[mid] == target) return mid;
        // Determine which side is sorted
        if (nums[left] <= nums[mid]) { // left side is sorted
            if (target >= nums[left] && target < nums[mid]) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        } else { // right side is sorted
            if (target > nums[mid] && target <= nums[right]) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
    }
    return -1;
}

public double trimMean(int[] arr) {
