public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length == 0) return true;
    if (k <= 0) return false;
    int n = arr.length;
    if (n % 2 != 0) return false; // cannot pair all elements if odd count
    int[] freq = new int[k];
    for (int num : arr) {
        int rem = num % k;
        if (rem < 0) rem += k;
        freq[rem]++;
    }
    for (int r = 0; r <= k / 2; r++) {
        int complement = (k - r) % k;
        if (r == complement) { // only when k even and r == k/2 or r == 0
            if (freq[r] % 2 != 0) return false;
        } else {
            if (freq[r] != freq[complement]) return false;
        }
    }
    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Build adjacency list representation of the tree
    @SuppressWarnings("unchecked")
    java.util.List<Integer>[] graph = new java.util.ArrayList[n];
    for (int i = 0; i < n; i++) {
        graph[i] = new java.util.ArrayList<>();
    }
    for (int[] edge : edges) {
        int u = edge[0], v = edge[1];
        graph[u].add(v);
        graph[v].add(u);
    }

    // Total time accumulator (wrapped in array to modify in recursive helper)
    int[] totalTime = new int[1];
    dfs(0, -1, graph, hasApple, totalTime);
    return totalTime[0];
}

private boolean dfs(int node, int parent,
                    java.util.List<Integer>[] graph,
                    boolean[] hasApple,
                    int[] totalTime) {
    boolean containsApple = hasApple[node];
    for (int next : graph[node]) {
        if (next == parent) continue;
        boolean childHasApple = dfs(next, node, graph, hasApple, totalTime);
        if (childHasApple) {
            // Traverse to child and back: 2 seconds per edge
            totalTime[0] += 2;
            containsApple = true;
        }
    }
    return containsApple;
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) return "";
    TreeMap<Character, Integer> freq = new TreeMap<>();
    for (char c : s.toCharArray()) {
        freq.merge(c, 1, Integer::sum);
    }
    StringBuilder result = new StringBuilder();
    while (!freq.isEmpty()) {
        // ascending phase
        Character key = freq.firstKey();
        result.append(key);
        decrementKey(freq,key);
        char last = key;
        while (true) {
            Character next = freq.higherKey(last);
            if (next == null) break;
            result.append(next);
            decrementKey(freq,next);
            last = next;
        }
        // descending phase
        if (freq.isEmpty()) break; // nothing left
        Character lastKey = freq.lastKey();
        result.append(lastKey);
        decrementKey(freq,lastKey);
        last = lastKey;
        while (true) {
            Character prev = freq.lowerKey(last);
            if (prev == null) break;
            result.append(prev);
            decrementKey(freq, prev);
            last = prev;
        }
    }
    return result.toString();
}

private void decrementKey(TreeMap<Character,Integer> map, Character key) {
    int cnt = map.get(key);
    if (cnt == 1) map.remove(key);
    else map.put(key, cnt-1);
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length < 2) {
        return false;
    }
    int n = nums.length;
    int total = 0;
    for (int num : nums) {
        total += num;
    }

    // dp[k] holds the set of achievable sums using exactly k elements
    @SuppressWarnings("unchecked")
    HashSet<Integer>[] dp = new HashSet[n + 1];
    for (int i = 0; i <= n; i++) {
        dp[i] = new HashSet<>();
    }
    dp[0].add(0);

    for (int num : nums) {
        // Iterate backwards to avoid using the same element multiple times
        for (int k = n - 1; k >= 0; k--) {
            if (dp[k].isEmpty()) continue;
            for (int s : dp[k]) {
                dp[k + 1].add(s + num);
            }
        }
    }

    for (int k = 1; k <= n / 2; k++) { // symmetric, checking k up to n/2 is enough
        if ((total * k) % n != 0) continue;
        int target = (total * k) / n;
        if (dp[k].contains(target)) {
            return true;
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null) {
        throw new IllegalArgumentException("Input array cannot be null");
    }
    int n = cost.length;
    if (n == 0) {
        return 0;
    }
    if (n == 1) {
        return cost[0];
    }
    int prev2 = cost[0];
    int prev1 = cost[1];
    int curr = 0;
    for (int i = 2; i < n; i++) {
        curr = Math.min(prev1, prev2) + cost[i];
        prev2 = prev1;
        prev1 = curr;
    }
    return Math.min(prev1, prev2);
}

public int uniqueMorseRepresentations(String[] words) {
    if (words == null || words.length == 0) {
        return 0;
    }
    String[] morse = {".-","-...","-.-.","-..",".","..-.","--.","....","..",
                      ".---","-.-",".-..","--","-.","---",".--.","--.-",".-.","...",
                      "-","..-","...-",".--","-..-","-.--","--.."};

    java.util.Set<String> set = new java.util.HashSet<>();
    for (String word : words) {
        if (word == null) {
            continue;
        }
        StringBuilder sb = new StringBuilder();
        for (char c : word.toCharArray()) {
            if (c >= 'a' && c <= 'z') {
                sb.append(morse[c - 'a']);
            } else if (c >= 'A' && c <= 'Z') {
                sb.append(morse[c - 'A']);
            } // non‑letter characters are ignored
        }
        set.add(sb.toString());
    }
    return set.size();
}

public boolean hasAllCodes(String s, int k) {
    if (s == null) return false;
    if (k < 0) return false;
    if (k == 0) return true; // empty substring is always present
    int n = s.length();
    // 2^k grows too fast; if k >= 31, it overflows int and 2^k > n
    if (k >= 31) return false;
    int total = 1 << k;
    if (n < total) return false; // cannot contain all substrings

    boolean[] seen = new boolean[total];
    int count = 0;
    for (int i = 0; i <= n - k; i++) {
        int code = 0;
        for (int j = i; j < i + k; j++) {
            code = (code << 1) | (s.charAt(j) - '0');
        }
        if (!seen[code]) {
            seen[code] = true;
            count++;
            if (count == total) return true; // all codes found early
        }
    }
    return count == total;
}

public int isPrefixOfWord(String sentence, String searchWord) {
    // Validate input parameters
    if (sentence == null || searchWord == null) {
        return -1;
    }

    // Trim the sentence and split it into words based on whitespace
    String trimmedSentence = sentence.trim();
    if (trimmedSentence.isEmpty()) {
        return -1;
    }

    String[] words = trimmedSentence.split("\\s+");
    for (int i = 0; i < words.length; i++) {
        try {
            if (words[i].startsWith(searchWord)) {
                // Return 1-based index of the matching word
                return i + 1;
            }
        } catch (Exception e) {
            // If any unexpected exception occurs while checking startsWith,
            // skip this word and continue.
            continue;
        }
    }

    // No matching prefix found
    return -1;
}

public int minInsertions(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int res = 0;
    int balance = 0;
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else if (c == ')') {
            if (balance == 0) {
                // Need an opening bracket before this closing bracket
                res++;
            } else {
                balance--;
            }
        }
    }
    // Any remaining unmatched '(' need closing brackets
    res += balance;
    return res;
}

public int minOperations(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be positive");
    }
    long sumAbs = 0L;
    for (int i = 0; i < n; i++) {
        long value = 2L * i + 1L;
        sumAbs += Math.abs(value - n);
    }
    // Each operation decreases the total absolute difference by 2.
    long operations = sumAbs / 2;
    return (int) operations;
}

