public int maxAbsoluteSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    int maxEnding = nums[0];
    int maxSoFar = nums[0];
    int minEnding = nums[0];
    int minSoFar = nums[0];
    for (int i = 1; i < nums.length; i++) {
        int n = nums[i];
        maxEnding = Math.max(n, maxEnding + n);
        maxSoFar = Math.max(maxSoFar, maxEnding);
        minEnding = Math.min(n, minEnding + n);
        minSoFar = Math.min(minSoFar, minEnding);
    }
    return Math.max(maxSoFar, -minSoFar);
}

public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        return 0;
    }
    // Generate Fibonacci numbers up to k
    int[] fib = new int[50]; // sufficient for int range
    int fibCount = 0;
    fib[fibCount++] = 1; // F1
    fib[fibCount++] = 1; // F2
    while (true) {
        int next = fib[fibCount - 1] + fib[fibCount - 2];
        if (next > k) {
            break;
        }
        fib[fibCount++] = next;
    }

    int remaining = k;
    int count = 0;
    // Greedy algorithm: pick the largest Fibonacci number not exceeding remaining
    for (int i = fibCount - 1; i >= 0 && remaining > 0; i--) {
        if (fib[i] <= remaining) {
            int times = remaining / fib[i];
            count += times;
            remaining -= times * fib[i];
        }
    }
    return count;
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }
    java.util.List<Integer> factors = new java.util.ArrayList<>();
    int sqrtN = (int) Math.sqrt(n);
    for (int i = 1; i <= sqrtN; i++) {
        if (n % i == 0) {
            factors.add(i);
            int other = n / i;
            if (other != i) {
                factors.add(other);
            }
        }
    }
    java.util.Collections.sort(factors);
    return (k - 1) < factors.size() ? factors.get(k - 1) : -1;
}

public String makeGood(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder stack = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char current = s.charAt(i);
        int len = stack.length();
        if (len > 0) {
            char top = stack.charAt(len - 1);
            // Check if current and top are the same letter with opposite cases
            if (Math.abs(top - current) == 32) {
                stack.setLength(len - 1); // remove the pair
                continue;
            }
        }
        stack.append(current); // push current character
    }
    return stack.toString();
}

public int maxUniqueSplit(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int[] maxRef = new int[]{0};
    dfs(0, new java.util.HashSet<>(), s, maxRef);
    return maxRef[0];
}

private void dfs(int pos, java.util.Set<String> used, String s, int[] maxRef) {
    if (pos == s.length()) {
        if (used.size() > maxRef[0]) {
            maxRef[0] = used.size();
        }
        return;
    }
    for (int end = pos + 1; end <= s.length(); end++) {
        String sub = s.substring(pos, end);
        if (!used.contains(sub)) {
            used.add(sub);
            dfs(end, used, s, maxRef);
            used.remove(sub);
        }
    }
}

public int minOperations(String[] logs) {
    if (logs == null) {
        return 0;
    }
    int depth = 0;
    for (String log : logs) {
        if (log == null) {
            continue;
        }
        if (log.equals("./")) {
            // stay in current folder, nothing to do
            continue;
        } else if (log.equals("../")) {
            // move up one folder if possible
            if (depth > 0) {
                depth--;
            }
        } else if (log.endsWith("/")) {
            // enter a new folder
            depth++;
        }
        // any other format is ignored as it does not represent a valid operation
    }
    // depth now represents how many levels away from the main folder we are
    return depth;
}

public String getSmallestString(int n, int k) {
    if (n <= 0) {
        throw new IllegalArgumentException("String length must be positive.");
    }
    if (k < n || k > 26L * n) {
        throw new IllegalArgumentException("k is out of valid range for given n.");
    }
    char[] chars = new char[n];
    // Initialize all to 'a'
    for (int i = 0; i < n; i++) {
        chars[i] = 'a';
    }
    int remaining = k - n; // amount we need to add to reach total k (each 'a' counts as 1)
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int inc = Math.min(25, remaining); // can increase up to 'z' (value 26)
        chars[i] = (char) ('a' + inc);
        remaining -= inc;
    }
    return new String(chars);
}

