public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    int[] bitCount = new int[32];
    for (int num : nums) {
        for (int i = 0; i < 32; i++) {
            if (((num >> i) & 1) != 0) {
                bitCount[i]++;
            }
        }
    }
    int result = 0;
    for (int i = 0; i < 32; i++) {
        if ((bitCount[i] % 3) != 0) {
            result |= (1 << i);
        }
    }
    return result;
}

public static int countDigitOne(int n) {
    if (n < 0) {
        return 0;
    }
    long count = 0L;
    long divisor = 1L;
    while (divisor <= n) {
        long high = n / (divisor * 10L);
        long cur = (n / divisor) % 10L;
        long low = n % divisor;
        count += high * divisor;
        if (cur > 1) {
            count += divisor;
        } else if (cur == 1) {
            count += low + 1;
        }
        divisor *= 10L;
    }
    return (int) count;
}

public static boolean isPowerOfTwo(int n) {
    // A power of two must be positive and have only one bit set in its binary representation.
    if (n <= 0) {
        return false;
    }
    // Using bitwise trick: a power of two has exactly one '1' bit.
    return (n & (n - 1)) == 0;
}

public static int addDigits(int num) {
    if (num < 0) {
        throw new IllegalArgumentException("num must be non-negative");
    }
    int sum = num;
    while (sum >= 10) {
        int temp = sum;
        int digitSum = 0;
        while (temp > 0) {
            digitSum += temp % 10;
            temp /= 10;
        }
        sum = digitSum;
    }
    return sum;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }
    int m = mat.length;
    int n = mat[0].length;
    int[][][] dp = new int[m][n][4]; // 0: horizontal, 1: vertical, 2: diagonal, 3: anti-diagonal
    int maxLen = 0;

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                dp[i][j][0] = (j > 0 ? dp[i][j - 1][0] : 0) + 1;          // horizontal
                dp[i][j][1] = (i > 0 ? dp[i - 1][j][1] : 0) + 1;          // vertical
                dp[i][j][2] = (i > 0 && j > 0 ? dp[i - 1][j - 1][2] : 0) + 1; // diagonal
                dp[i][j][3] = (i > 0 && j < n - 1 ? dp[i - 1][j + 1][3] : 0) + 1; // anti-diagonal

                int current = Math.max(
                        Math.max(dp[i][j][0], dp[i][j][1]),
                        Math.max(dp[i][j][2], dp[i][j][3])
                );
                if (current > maxLen) {
                    maxLen = current;
                }
            }
        }
    }
    return maxLen;
}

public static String addThousandSeparator(int n) {
    if (n == 0) {
        return "0";
    }
    boolean negative = n < 0;
    int value = Math.abs(n);
    StringBuilder sb = new StringBuilder();
    int count = 0;
    while (value > 0) {
        int digit = value % 10;
        sb.append((char) ('0' + digit));
        value /= 10;
        count++;
        if (value > 0 && count % 3 == 0) {
            sb.append('.');
        }
    }
    if (negative) {
        sb.append('-');
    }
    return sb.reverse().toString();
}

