public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    java.util.Deque<Integer> stack = new java.util.ArrayDeque<>();
    int maxArea = 0;
    for (int i = 0; i <= heights.length; i++) {
        int currentHeight = (i == heights.length) ? 0 : heights[i];
        while (!stack.isEmpty() && currentHeight <= heights[stack.peek()]) {
            int height = heights[stack.pop()];
            int width = stack.isEmpty() ? i : i - stack.peek() - 1;
            int area = height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack.push(i);
    }
    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int idx = 0;
    for (int sum = 0; sum <= m + n - 2; sum++) {
        if (sum % 2 == 0) {
            int startRow = Math.min(sum, m - 1);
            int endRow = Math.max(0, sum - n + 1);
            for (int i = startRow; i >= endRow; i--) {
                int j = sum - i;
                result[idx++] = mat[i][j];
            }
        } else {
            int startRow = Math.max(0, sum - n + 1);
            int endRow = Math.min(sum, m - 1);
            for (int i = startRow; i <= endRow; i++) {
                int j = sum - i;
                result[idx++] = mat[i][j];
            }
        }
    }
    return result;
}

public static int findSmallestInteger(int n) {
    if (n <= 0) return -1;
    String s = Integer.toString(n);
    char[] arr = s.toCharArray();

    int i = arr.length - 2;
    while (i >= 0 && arr[i] >= arr[i + 1]) {
        i--;
    }
    if (i < 0) {
        return -1;
    }

    int j = arr.length - 1;
    while (arr[j] <= arr[i]) {
        j--;
    }

    char temp = arr[i];
    arr[i] = arr[j];
    arr[j] = temp;

    int left = i + 1, right = arr.length - 1;
    while (left < right) {
        char t = arr[left];
        arr[left] = arr[right];
        arr[right] = t;
        left++;
        right--;
    }

    try {
        long result = Long.parseLong(new String(arr));
        if (result > Integer.MAX_VALUE) return -1;
        return (int) result;
    } catch (NumberFormatException e) {
        return -1;
    }
}

